// C++: src/messaging.cc toit::MessageDecoder::decode_large_integer
Object *MessageDecoder_decode_large_integer(MessageDecoder *self)
/*@ requires dec(self, ?fb, ?proc, ?ids, ?fmt, ?b, ?size, ?cap, ?c, ?st0, ?k) &*& c <= cap &*&
             [?fp]process(proc, ?prog, ids) &*& heap(?objs, ?H); @*/
/*@ ensures dec(self, fb, proc, ids, fmt, b, size, cap, ?c2, ?st, k) &*& [fp]process(proc, prog, ids) &*&
            heap(?objs2, ?H2) &*& grows(objs, H, objs2, H2) == true &*& good(objs2, result) == true &*&
            (st == MessageDecoder_DECODE_SUCCESS ? c2 <= cap : true); @*/
{
  //@ grows_refl(objs, H);
  //@ truncate_zero();
  int64 value = /*@truncating@*/(int64)MessageDecoder_read_uint64(self);
  if (value == 0 && MessageDecoder_overflown(self)) {
    return MessageDecoder_mark_malformed(self);
  }
  //@ open dec(self, fb, proc, ids, fmt, b, size, cap, ?c1, ?st1, k);
  LargeInteger *result = ObjectHeap_allocate_large_integer(Process_object_heap(self->process_), value);
  //@ close dec(self, fb, proc, ids, fmt, b, size, cap, c1, st1, k);
  //@ open allocated(objs, H, proc, result, ?objs1, ?H1);
  //@ if (result != 0) grows_alloc(objs, H, result, H1);
  if (result == 0) {
    return MessageDecoder_mark_allocation_failed(self);
  }
  return result;
}

// C++: src/messaging.cc toit::MessageDecoder::decode_array
Object *MessageDecoder_decode_array(MessageDecoder *self)
/*@ requires dec(self, ?fb, ?proc, ?ids, ?fmt, ?b, ?size, ?cap, ?c, ?st0, ?k) &*& c <= cap &*&
             [?fp]process(proc, ?prog, ids) &*& self->nesting_ |-> ?n &*& 0 <= n &*& n <= MESSAGING_DECODING_MAX_NESTING &*&
             heap(?objs, ?H); @*/
/*@ ensures dec(self, fb, proc, ids, fmt, b, size, cap, ?c2, ?st, ?k2) &*& [fp]process(proc, prog, ids) &*&
            self->nesting_ |-> n &*& heap(?objs2, ?H2) &*& grows(objs, H, objs2, H2) == true &*& good(objs2, result) == true &*&
            (st == MessageDecoder_DECODE_SUCCESS ? c2 <= cap + 1 : true); @*/
{
  //@ grows_refl(objs, H);
  word length = /*@truncating@*/(word)MessageDecoder_read_cardinal(self);
  if (length == 0 && MessageDecoder_overflown(self)) {
    return MessageDecoder_mark_malformed(self);
  }
  if (length < 0 || length > MessageDecoder_remaining(self) || length > Array_max_length_in_process()) {
    return MessageDecoder_mark_malformed(self);
  }
  //@ open dec(self, fb, proc, ids, fmt, b, size, cap, ?c1, ?st1, k);
  //@ assert fmt == MESSAGE_FORMAT_TISON ? length <= cap - c1 : true;
  Array *result = ObjectHeap_allocate_array(Process_object_heap(self->process_), length, Smi_zero());
  //@ close dec(self, fb, proc, ids, fmt, b, size, cap, c1, st1, k);
  //@ open allocated(objs, H, proc, result, ?objs1, ?H1);
  //@ if (result != 0) grows_alloc(objs, H, result, H1);
  if (result == 0) {
    return MessageDecoder_mark_allocation_failed(self);
  }
  for (word i = 0; i < length; i++)
  /*@ invariant dec(self, fb, proc, ids, fmt, b, size, cap, ?ci, ?sti, ?ki) &*& ci <= cap + 1 &*&
                [fp]process(proc, prog, ids) &*& self->nesting_ |-> n &*& 0 <= i &*&
                heap(?objsi, ?Hi) &*& grows(objs, H, objsi, Hi) == true &*& mem(result, objsi) == true &*&
                has_tag(Hi, result, ARRAY_TAG) == true &*& o_len(Hi(result)) == length; @*/
  {
    Object *inner = MessageDecoder_decode_any(self);
    //@ assert heap(?objs3, ?H3);
    //@ grows_trans(objs, H, objsi, Hi, objs3, H3);
    if (!MessageDecoder_success(self)) {
      return inner;
    }
    //@ grows_keeps(objsi, Hi, objs3, H3, result);
    Array_at_put__word_Objectp(result, i, inner);
    //@ assert heap(objs3, ?H4);
    //@ put_step(objs, H, objs3, H3, H4, result);
  }
  return result;
}

// C++: src/messaging.cc toit::MessageDecoder::decode_map
Object *MessageDecoder_decode_map(MessageDecoder *self)
/*@ requires dec(self, ?fb, ?proc, ?ids, ?fmt, ?b, ?sz, ?cap, ?c, ?st0, ?k) &*& c <= cap &*&
             [?fp]process(proc, ?prog, ids) &*& self->nesting_ |-> ?n &*& 0 <= n &*& n <= MESSAGING_DECODING_MAX_NESTING &*&
             heap(?objs, ?H); @*/
/*@ ensures dec(self, fb, proc, ids, fmt, b, sz, cap, ?c2, ?st, ?k2) &*& [fp]process(proc, prog, ids) &*&
            self->nesting_ |-> n &*& heap(?objs2, ?H2) &*& grows(objs, H, objs2, H2) == true &*& good(objs2, result) == true &*&
            (st == MessageDecoder_DECODE_SUCCESS ? c2 <= cap + 1 : true); @*/
{
  //@ grows_refl(objs, H);
  word size = /*@truncating@*/(word)MessageDecoder_read_cardinal(self);
  if (size == 0 && MessageDecoder_overflown(self)) {
    return MessageDecoder_mark_malformed(self);
  }
  if (size < 0 || size > MessageDecoder_remaining(self) / 2 || size > Array_max_length_in_process() / 2) {
    return MessageDecoder_mark_malformed(self);
  }
  //@ open dec(self, fb, proc, ids, fmt, b, sz, cap, ?c1, ?st1, k);
  //@ assert fmt == MESSAGE_FORMAT_TISON ? 2 * size <= cap - c1 : true;
  Instance *result = ObjectHeap_allocate_instance(Process_object_heap(self->process_), Program_map_class_id(self->program_));
  //@ close dec(self, fb, proc, ids, fmt, b, sz, cap, c1, st1, k);
  //@ open allocated(objs, H, proc, result, ?objs1, ?H1);
  //@ if (result != 0) grows_alloc(objs, H, result, H1);
  if (result == 0) {
    return MessageDecoder_mark_allocation_failed(self);
  }
  //@ int fields = class_fields(map_cid(ids));
  if (size == 0) {
    Instance_at_put__word_Smip(result, Instance_MAP_SIZE_INDEX, Smi_from(0));
    //@ assert heap(objs1, ?Ha);
    //@ put_step(objs, H, objs1, H1, Ha, result);
    Instance_at_put__word_Smip(result, Instance_MAP_SPACES_LEFT_INDEX, Smi_from(0));
    //@ assert heap(objs1, ?Hb);
    //@ put_step(objs, H, objs1, Ha, Hb, result);
    //@ open dec(self, fb, proc, ids, fmt, b, sz, cap, c1, st1, k);
    Instance_at_put__word_Objectp(result, Instance_MAP_INDEX_INDEX, Program_null_object(self->program_));
    //@ assert heap(objs1, ?Hc);
    //@ put_step(objs, H, objs1, Hb, Hc, result);
    Instance_at_put__word_Objectp(result, Instance_MAP_BACKING_INDEX, Program_null_object(self->program_));
    //@ assert heap(objs1, ?Hd);
    //@ put_step(objs, H, objs1, Hc, Hd, result);
    //@ close dec(self, fb, proc, ids, fmt, b, sz, cap, c1, st1, k);
    return result;
  }
  //@ open dec(self, fb, proc, ids, fmt, b, sz, cap, c1, st1, k);
  Array *array = ObjectHeap_allocate_array(Process_object_heap(self->process_), size * 2, Smi_zero());
  //@ close dec(self, fb, proc, ids, fmt, b, sz, cap, c1, st1, k);
  //@ open allocated(objs1, H1, proc, array, ?objs2a, ?H2a);
  //@ if (array != 0) { grows_alloc(objs1, H1, array, H2a); grows_keeps(objs1, H1, objs2a, H2a, result); grows_trans(objs, H, objs1, H1, objs2a, H2a); }
  if (array == 0) {
    return MessageDecoder_mark_allocation_failed(self);
  }
  for (word i = 0; i < size * 2; i++)
  /*@ invariant dec(self, fb, proc, ids, fmt, b, sz, cap, ?ci, ?sti, ?ki) &*& ci <= cap + 1 &*&
                [fp]process(proc, prog, ids) &*& self->nesting_ |-> n &*& 0 <= i &*&
                heap(?objsi, ?Hi) &*& grows(objs, H, objsi, Hi) == true &*&
                mem(array, objsi) == true &*& has_tag(Hi, array, ARRAY_TAG) == true &*& o_len(Hi(array)) == size * 2 &*&
                mem(result, objsi) == true &*& has_tag(Hi, result, INSTANCE_TAG) == true &*& o_len(Hi(result)) == fields; @*/
  {
    Object *inner = MessageDecoder_decode_any(self);
    //@ assert heap(?objs3, ?H3);
    //@ grows_trans(objs, H, objsi, Hi, objs3, H3);
    if (!MessageDecoder_success(self)) {
      return inner;
    }
    //@ grows_keeps(objsi, Hi, objs3, H3, array);
    //@ grows_keeps(objsi, Hi, objs3, H3, result);
    Array_at_put__word_Objectp(array, i, inner);
    //@ assert heap(objs3, ?H4);
    //@ put_step(objs, H, objs3, H3, H4, array);
    //@ grows_keeps(objs3, H3, objs3, H4, result);
  }
  //@ assert heap(?objs5, ?H5);
  Instance_at_put__word_Smip(result, Instance_MAP_SIZE_INDEX, Smi_from(size));
  //@ assert heap(objs5, ?He);
  //@ put_step(objs, H, objs5, H5, He, result);
  Instance_at_put__word_Smip(result, Instance_MAP_SPACES_LEFT_INDEX, Smi_from(0));
  //@ assert heap(objs5, ?Hf);
  //@ put_step(objs, H, objs5, He, Hf, result);
  //@ open dec(self, fb, proc, ids, fmt, b, sz, cap, ?c6, ?st6, ?k6);
  Instance_at_put__word_Objectp(result, Instance_MAP_INDEX_INDEX, Program_null_object(self->program_));
  //@ close dec(self, fb, proc, ids, fmt, b, sz, cap, c6, st6, k6);
  //@ assert heap(objs5, ?Hg);
  //@ put_step(objs, H, objs5, Hf, Hg, result);
  Instance_at_put__word_Objectp(result, Instance_MAP_BACKING_INDEX, array);
  //@ assert heap(objs5, ?Hh);
  //@ put_step(objs, H, objs5, Hg, Hh, result);
  return result;
}

// C++: src/messaging.cc toit::MessageDecoder::decode_any
Object *MessageDecoder_decode_any(MessageDecoder *self)
/*@ requires dec(self, ?fb, ?proc, ?ids, ?fmt, ?b, ?size, ?cap, ?c, ?st0, ?k) &*& c <= cap + 8 &*&
             [?fp]process(proc, ?prog, ids) &*& self->nesting_ |-> ?n &*& 0 <= n &*& n <= MESSAGING_DECODING_MAX_NESTING &*&
             heap(?objs, ?H); @*/
/*@ ensures dec(self, fb, proc, ids, fmt, b, size, cap, ?c2, ?st, ?k2) &*& [fp]process(proc, prog, ids) &*&
            self->nesting_ |-> n &*& heap(?objs2, ?H2) &*& grows(objs, H, objs2, H2) == true &*& good(objs2, result) == true &*&
            (st == MessageDecoder_DECODE_SUCCESS ? c2 <= cap + 1 : true); @*/
{
  NestingTracker tracking;
  //@ grows_refl(objs, H);
  NestingTracker_ctor(&tracking, &self->nesting_);
  if (self->nesting_ > (int)MESSAGING_DECODING_MAX_NESTING) {
    {
      Object * result0 = MessageDecoder_mark_malformed(self);
      NestingTracker_dtor(&tracking);
      return result0;
    }
  }
  int tag = (int)MessageDecoder_read_uint8(self);
  switch (tag) {
    case (int)TAG_OVERFLOWN:
      {
        Object * result1 = MessageDecoder_mark_malformed(self);
        NestingTracker_dtor(&tracking);
        return result1;
      }
    case (int)TAG_POSITIVE_SMI:
      {
        uword value = MessageDecoder_read_cardinal(self);
        if (value > (uword)Smi_MAX_SMI_VALUE) {
          {
            Object * result2 = MessageDecoder_mark_malformed(self);
            NestingTracker_dtor(&tracking);
            return result2;
          }
        }
        {
          Object * result3 = Smi_from((word)value);
          NestingTracker_dtor(&tracking);
          return result3;
        }
      }
    case (int)TAG_NEGATIVE_SMI:
      {
        uword value = MessageDecoder_read_cardinal(self);
        if (value > (uword)-Smi_MIN_SMI_VALUE) {
          {
            Object * result4 = MessageDecoder_mark_malformed(self);
            NestingTracker_dtor(&tracking);
            return result4;
          }
        }
        {
          Object * result5 = Smi_from(-(word)value);
          NestingTracker_dtor(&tracking);
          return result5;
        }
      }
    case (int)TAG_NULL:
      //@ open dec(self, fb, proc, ids, fmt, b, size, cap, c + 1, st0, k);
      {
        Object * result6 = Program_null_object(self->program_);
        //@ close dec(self, fb, proc, ids, fmt, b, size, cap, c + 1, st0, k);
        NestingTracker_dtor(&tracking);
        return result6;
      }
    case (int)TAG_TRUE:
      //@ open dec(self, fb, proc, ids, fmt, b, size, cap, c + 1, st0, k);
      {
        Object * result7 = Program_true_object(self->program_);
        //@ close dec(self, fb, proc, ids, fmt, b, size, cap, c + 1, st0, k);
        NestingTracker_dtor(&tracking);
        return result7;
      }
    case (int)TAG_FALSE:
      //@ open dec(self, fb, proc, ids, fmt, b, size, cap, c + 1, st0, k);
      {
        Object * result8 = Program_false_object(self->program_);
        //@ close dec(self, fb, proc, ids, fmt, b, size, cap, c + 1, st0, k);
        NestingTracker_dtor(&tracking);
        return result8;
      }
    case (int)TAG_STRING:
      {
        Object * result9 = MessageDecoder_decode_string(self, false);
        NestingTracker_dtor(&tracking);
        return result9;
      }
    case (int)TAG_STRING_INLINE:
      {
        Object * result10 = MessageDecoder_decode_string(self, true);
        NestingTracker_dtor(&tracking);
        return result10;
      }
    case (int)TAG_ARRAY:
      {
        Object * result11 = MessageDecoder_decode_array(self);
        NestingTracker_dtor(&tracking);
        return result11;
      }
    case (int)TAG_MAP:
      {
        Object * result12 = MessageDecoder_decode_map(self);
        NestingTracker_dtor(&tracking);
        return result12;
      }
    case (int)TAG_BYTE_ARRAY:
      {
        Object * result13 = MessageDecoder_decode_byte_array(self, false);
        NestingTracker_dtor(&tracking);
        return result13;
      }
    case (int)TAG_BYTE_ARRAY_INLINE:
      {
        Object * result14 = MessageDecoder_decode_byte_array(self, true);
        NestingTracker_dtor(&tracking);
        return result14;
      }
    case (int)TAG_DOUBLE:
      {
        Object * result15 = MessageDecoder_decode_double(self);
        NestingTracker_dtor(&tracking);
        return result15;
      }
    case (int)TAG_LARGE_INTEGER:
      {
        Object * result16 = MessageDecoder_decode_large_integer(self);
        NestingTracker_dtor(&tracking);
        return result16;
      }
    default:
      //@ open dec(self, fb, proc, ids, fmt, b, size, cap, c + 1, st0, k);
      if (!MessageDecoder_decoding_tison(self)) {
        printf("[message decoder: unhandled message tag: %d]\n", tag);
      }
    //@ close dec(self, fb, proc, ids, fmt, b, size, cap, c + 1, st0, k);
      {
        Object * result17 = MessageDecoder_mark_malformed(self);
        NestingTracker_dtor(&tracking);
        return result17;
      }
  }
  {
    Object * result18 = 0;
    NestingTracker_dtor(&tracking);
    return result18;
  }
}

// C++: src/messaging.cc toit::TisonDecoder::decode
Object *TisonDecoder_decode(TisonDecoder *self)
/*@ requires dec(self, ?fb, ?proc, ?ids, MESSAGE_FORMAT_TISON, ?b, ?size, ?cap, 0, MessageDecoder_DECODE_SUCCESS, ?k) &*&
             [?fp]process(proc, ?prog, ids) &*& self->nesting_ |-> 0 &*& heap(?objs, ?H); @*/
/*@ ensures dec(self, fb, proc, ids, MESSAGE_FORMAT_TISON, b, size, cap, ?c2, ?st, ?k2) &*& [fp]process(proc, prog, ids) &*&
            self->nesting_ |-> 0 &*& heap(?objs2, ?H2) &*& grows(objs, H, objs2, H2) == true &*& good(objs2, result) == true &*&
            (st == MessageDecoder_DECODE_SUCCESS ? c2 == cap : true); @*/
{
  //@ grows_refl(objs, H);
  //@ dec_facts(self);
  // ASSERT(MessageDecoder_decoding_tison(self)): release build, not evaluated.
  //@ shiftleft_def(1, succ(succ(succ(succ(succ(succ(succ(succ(zero)))))))));
  uint32 expected = TISON_MARKER | (uint32)(TISON_VERSION << TISON_VERSION_SHIFT);
  uint32 marker = MessageDecoder_read_uint32(self);
  if (marker != expected) {
    return MessageDecoder_mark_malformed(self);
  }
  word payload_size = /*@truncating@*/(word)MessageDecoder_read_cardinal(self);
  if (payload_size != MessageDecoder_remaining(self)) {
    return MessageDecoder_mark_malformed(self);
  }
  Object *result = MessageDecoder_decode_any(self);
  if (!MessageDecoder_success(self)) {
    return result;
  }
  if (MessageDecoder_remaining(self) != 0) {
    return MessageDecoder_mark_malformed(self);
  }
  return result;
}

// C++: src/messaging.h toit::MessageDecoder::decode
Object *MessageDecoder_decode(MessageDecoder *self)
/*@ requires dec(self, ?fb, ?proc, ?ids, MESSAGE_FORMAT_IPC, ?b, ?size, ?cap, 0, MessageDecoder_DECODE_SUCCESS, ?k) &*&
             [?fp]process(proc, ?prog, ids) &*& self->nesting_ |-> 0 &*& heap(?objs, ?H); @*/
/*@ ensures dec(self, fb, proc, ids, MESSAGE_FORMAT_IPC, b, size, cap, ?c2, ?st, ?k2) &*& [fp]process(proc, prog, ids) &*&
            self->nesting_ |-> 0 &*& heap(?objs2, ?H2) &*& grows(objs, H, objs2, H2) == true &*& good(objs2, result) == true; @*/
{
  //@ dec_facts(self);
  // ASSERT(!MessageDecoder_decoding_tison(self)): release build, not evaluated.
  return MessageDecoder_decode_any(self);
}

